using System.ComponentModel;
using ModelContextProtocol.Server;

namespace HttpMcpServer.Tools;

[McpServerToolType]
public static class GreetingTools
{
    [McpServerTool, Description("Returns a personalised greeting message.")]
    public static string Greet(
        [Description("Name of the person to greet")] string name) =>
        $"Hello, {name}! Welcome to the MCP HTTP server.";
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace HttpMcpServer.Resources;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns current application configuration data.")]
    public static string GetAppSettings() =>
        JsonSerializer.Serialize(new
        {
            AppName = "HttpMcpServer",
            Version = "1.0.0",
            MaxConnections = 100,
            Features = new { Logging = true, Caching = false }
        }, new JsonSerializerOptions { WriteIndented = true });
}

